ALTER TABLE workspace_members ADD CONSTRAINT workspace_members_role_check CHECK (role IN ('OWNER','ADMIN','MANAGER','VIEWER'));
CREATE TABLE webhook_events (id text PRIMARY KEY, provider text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, status text NOT NULL DEFAULT 'reserved', error_code text);
CREATE TABLE telegram_connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, telegram_user_id_ciphertext bytea NOT NULL, encryption_key_id text NOT NULL, enabled boolean NOT NULL DEFAULT true, connected_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id));
CREATE TABLE email_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE, kind text NOT NULL, recipient_ciphertext bytea NOT NULL, provider_message_id text, idempotency_key text NOT NULL UNIQUE, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz);
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid REFERENCES workspaces(id) ON DELETE SET NULL, actor_user_id uuid REFERENCES users(id) ON DELETE SET NULL, action text NOT NULL, resource_type text NOT NULL, resource_id text, metadata jsonb NOT NULL DEFAULT '{}', ip_hash text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_logs_workspace_created_idx ON audit_logs(workspace_id,created_at DESC);
